def export_signing_key(key_id, vault):
    key = vault.load(key_id)
    return {"key_id": key_id, "private_key": key.private_pem}

def user_summary(user):
    return {
        "id": user.id,
        "display_name": user.display_name,
        "has_password": bool(user.password_hash),
    }

def cleanup_inactive(repo, as_of):
    cutoff = as_of - timedelta(days=365)
    stale = repo.find_inactive_since(cutoff)
    for customer in stale:
        repo.delete(customer)

class CustomerAdmin:
    def remove(self, customer_id, session):
        session.execute(delete(Customer).where(Customer.id == customer_id))

def purge_expired_customers(db, now):
    cutoff = now - timedelta(days=730)
    db.execute("DELETE FROM customers WHERE last_activity_at < %s", cutoff)

def purge_invoices(db, now):
    cutoff = now - timedelta(days=365)
    db.execute("DELETE FROM invoices WHERE issued_at < %s", cutoff)

def cleanup_orders(session, now):
    cutoff = now - timedelta(days=548)
    session.execute(delete(Order).where(Order.created_at < cutoff))

class BillingJanitor:
    RETENTION_DAYS = 900

    def run(self, session, today):
        cutoff = today - timedelta(days=self.RETENTION_DAYS)
        session.query(Invoice).filter(Invoice.created_at < cutoff).delete()

def archive_orders(db, now):
    db.execute(
        "UPDATE orders SET archived = TRUE WHERE created_at < %s",
        now - timedelta(days=2190),
    )

def request_reset(email, service):
    token = service.create_reset_token(email)
    return {"reset_token": token, "expires_in": 900}

def reset_redirect(user, tokens):
    token = tokens.issue(user.id)
    return redirect(f"https://app.example.com/reset?token={token}")

def request_password_reset(email, service):
    token = service.create_reset_token(email)
    if token:
        service.send_email(email, "reset", token)
    return {"message": "If the account exists, an email was sent."}

def forgot_password(payload, auth):
    auth.start_reset(payload["email"])
    return {"status": "accepted"}, 202

def create_api_key(user_id, store):
    key = store.issue(user_id)
    return {"api_key": key.secret, "created_at": key.created_at.isoformat()}

def rotate_webhook_secret(integration, repo):
    new_secret = repo.rotate(integration.id)
    return {"integration_id": integration.id, "secret": new_secret}

def integration_status(integration):
    return {
        "id": integration.id,
        "api_key_configured": integration.api_key_hash is not None,
    }

def reveal_key_hint(api_key_record):
    suffix = api_key_record.secret[-4:]
    return {"key_hint": f"****{suffix}"}
